INSERT INTO `aggregator_item` (`iid`, `langcode`, `fid`, `title`, `link`, `author`, `description`, `timestamp`, `guid`) VALUES
(740, 'en', 9, 'Global and Component Style Settings with CSS Variables — Sara Soueidan', 'http://feedproxy.google.com/~r/brad-frosts-blog/~3/qf1WBgk9mFY/', 'Brad Frost', 'Sara shares how she&#8217;s structuring her CSS with CSS custom properties. This is all very relevant to the work I&#8217;m doing now. Source: Global and Component Style Settings with CSS Variables — Sara Soueidan – Freelance-Front-End UI/UX Developer<img src=\"//bradfrost.com/wp-content/plugins/matomo/app/matomo.php?idsite=1&amp;rec=1&amp;url=https%3A%2F%2Fbradfrost.com%2Fblog%2Flink%2Fglobal-and-component-style-settings-with-css-variables-sara-soueidan%2F&amp;action_name=Global%20and%20Component%20Style%20Settings%20with%20CSS%20Variables%20%E2%80%94%20Sara%20Soueidan&amp;urlref=https%3A%2F%2Fbradfrost.com%2Ffeed%2F\" style=\"border:0;width:0;height:0\" width=\"0\" height=\"0\" alt=\"\" />', 1591805453, 'https://bradfrost.com/?p=13729'),
(741, 'en', 9, 'Nice, Very Nice', 'http://feedproxy.google.com/~r/brad-frosts-blog/~3/lvsHDNITr8o/', 'Brad Frost', 'Nice, Very Nice is a collection of UX/UI patterns for your inspiration.<img src=\"//bradfrost.com/wp-content/plugins/matomo/app/matomo.php?idsite=1&amp;rec=1&amp;url=https%3A%2F%2Fbradfrost.com%2Fblog%2Flink%2Fnice-very-nice%2F&amp;action_name=Nice%2C%20Very%20Nice&amp;urlref=https%3A%2F%2Fbradfrost.com%2Ffeed%2F\" style=\"border:0;width:0;height:0\" width=\"0\" height=\"0\" alt=\"\" />', 1590969646, 'https://bradfrost.com/?p=13725'),
(742, 'en', 9, 'RWD Weekly #411 Interview Series with Brad Frost &#124; Responsive Web Design', 'http://feedproxy.google.com/~r/brad-frosts-blog/~3/O4wqup5GrbA/', 'Brad Frost', 'I had the privilege of being interviewed in Justin Avery&#8217;s long-running RWD Weekly newsletter about the state of responsive design  10 years in. I weigh in on client expectations around responsive design, still unsolved responsive design challenges, and other things.<img src=\"//bradfrost.com/wp-content/plugins/matomo/app/matomo.php?idsite=1&amp;rec=1&amp;url=https%3A%2F%2Fbradfrost.com%2Fblog%2Flink%2Frwd-weekly-411-interview-series-with-brad-frost-responsive-web-design%2F&amp;action_name=RWD%20Weekly%20%23411%20Interview%20Series%20with%20Brad%20Frost%20%7C%20Responsive%20Web%20Design&amp;urlref=https%3A%2F%2Fbradfrost.com%2Ffeed%2F\" style=\"border:0;width:0;height:0\" width=\"0\" height=\"0\" alt=\"\" />', 1590505677, 'https://bradfrost.com/?p=13723'),
(743, 'en', 9, 'The Isolation Station with Brad Frost', 'http://feedproxy.google.com/~r/brad-frosts-blog/~3/y5VTeczGmEc/', 'Brad Frost', 'I got to share my quarantine playlist on The Isolation Station, and gave a bit of context behind some of the picks in my interview.<img src=\"//bradfrost.com/wp-content/plugins/matomo/app/matomo.php?idsite=1&amp;rec=1&amp;url=https%3A%2F%2Fbradfrost.com%2Fblog%2Flink%2Fthe-isolation-station-with-brad-frost%2F&amp;action_name=The%20Isolation%20Station%20with%20Brad%20Frost&amp;urlref=https%3A%2F%2Fbradfrost.com%2Ffeed%2F\" style=\"border:0;width:0;height:0\" width=\"0\" height=\"0\" alt=\"\" />', 1590002419, 'https://bradfrost.com/?p=13718'),
(744, 'en', 9, 'The story behind that photo of the Pinto in front of the Mt. St. Helens', 'http://feedproxy.google.com/~r/brad-frosts-blog/~3/Q-ALfckYoAw/', 'Brad Frost', 'Being that Mt. St. Helens blew before I was born, I had never seen this photo. It&#8217;s wild, and the story behind it is even wilder! Source: The story behind that photo of the Pinto in front of the Mt. [&#8230;]<img src=\"//bradfrost.com/wp-content/plugins/matomo/app/matomo.php?idsite=1&amp;rec=1&amp;url=https%3A%2F%2Fbradfrost.com%2Fblog%2Flink%2Fthe-story-behind-that-photo-of-the-pinto-in-front-of-the-mt-st-helens%2F&amp;action_name=The%20story%20behind%20that%20photo%20of%20the%20Pinto%20in%20front%20of%20the%20Mt.%20St.%20Helens&amp;urlref=https%3A%2F%2Fbradfrost.com%2Ffeed%2F\" style=\"border:0;width:0;height:0\" width=\"0\" height=\"0\" alt=\"\" />', 1589814457, 'https://bradfrost.com/?p=13712'),
(751, 'en', 10, '3 Great Ways to Monetize Content', 'http://feedproxy.google.com/~r/Bludice/~3/o4H-4vlFFGY/3-great-ways-to-monetize-content', 'David Walsh', '<p>Monetizing content on the web usually boils down to one thing: advertisements. The problem with adding advertisements to your website, especially from the popular ad services, is that they can be slow and they certainly don&#8217;t protect user privacy. That&#8217;s where alternative monetizing opportunities come into play. Let&#8217;s take a quick look at a few [&#8230;]</p>\n<p>The post <a rel=\"nofollow\" href=\"https://davidwalsh.name/3-great-ways-to-monetize-content\">3 Great Ways to Monetize Content</a> appeared first on <a rel=\"nofollow\" href=\"https://davidwalsh.name\">David Walsh Blog</a>.</p>\n<p><a href=\"https://tkjs.us/dwb\"><img style=\"margin:0 auto\" alt=\"\" src=\"https://davidwalsh.name/demo/tjs_block-1.svg\"></a></p>\n', 1591617292, 'https://davidwalsh.name/?p=27142'),
(752, 'en', 10, 'Are You a Developer?', 'http://feedproxy.google.com/~r/Bludice/~3/eR0QzTbvAbs/are-you-a-developer', 'Landon Schropp', '<p>“You’re not really a developer. Sooner or later people are going to realize you don’t know what you’re talking about. You’re just not good enough.” You’ve probably had thoughts like these at one point or another. You’ve never heard someone else tell you that you’re not a developer, but you’re still thinking it. You may [&#8230;]</p>\n<p>The post <a rel=\"nofollow\" href=\"https://davidwalsh.name/are-you-a-developer\">Are You a Developer?</a> appeared first on <a rel=\"nofollow\" href=\"https://davidwalsh.name\">David Walsh Blog</a>.</p>\n<p><a href=\"https://tkjs.us/dwb\"><img style=\"margin:0 auto\" alt=\"\" src=\"https://davidwalsh.name/demo/tjs_block-1.svg\"></a></p>\n', 1590583367, 'https://davidwalsh.name/?p=27135'),
(753, 'en', 10, 'Devising the Cloak of Invisibility in JavaScript', 'http://feedproxy.google.com/~r/Bludice/~3/G3atVNVxsls/javascript-steganography', 'Mohan Pierce', '<p>Steganography. The art of hiding something right under your nose. For as long as humans have been alive, we’ve been trying to hide things — whether it’s our last slice of pizza or the location of a buried treasure. Do you remember the cool invisible lemon ink trick, where we’d write the secret message with [&#8230;]</p>\n<p>The post <a rel=\"nofollow\" href=\"https://davidwalsh.name/javascript-steganography\">Devising the Cloak of Invisibility in JavaScript</a> appeared first on <a rel=\"nofollow\" href=\"https://davidwalsh.name\">David Walsh Blog</a>.</p>\n<p><a href=\"https://tkjs.us/dwb\"><img style=\"margin:0 auto\" alt=\"\" src=\"https://davidwalsh.name/demo/tjs_block-1.svg\"></a></p>\n', 1590416149, 'https://davidwalsh.name/?p=27122'),
(754, 'en', 12, 'Mirage JS Deep Dive: Understanding Timing, Response And Passthrough (Part 3)', 'https://www.smashingmagazine.com/2020/06/mirage-javascript-timing-response-passthrough/', NULL, 'Mirage JS was built to give frontend developers the ability to simulate actual backend API calls. So far, we have seen how we can create records with Mirage, intercept API requests via route handlers and, last but not least, how the shape of the data returned to us from Mirage is affected.\nIn this part of the series, we will see Mirage mechanism for simulating other aspects of an actual backend server like slow network, HTTP status code response, and also making requests to an actual backend even though Mirage is intercepting your frontend requests.', 1591792200, 'https://www.smashingmagazine.com/2020/06/mirage-javascript-timing-response-passthrough/'),
(755, 'en', 12, 'Is Your Website Stressing Out Visitors?', 'https://www.smashingmagazine.com/2020/06/website-stressing-out-visitors/', NULL, 'Stress is a nasty thing and many of us deal with it on a regular basis. Our jobs, school, homes, relationships, and even things going on around the world can trigger feelings of panic, unease, and depression. And those are just chronic stressors. Think about the small things that send your body into instant fight-or-flight mode on a daily basis (e.g. traffic jams, unhelpful customer service reps, getting sick when you have a big project due).', 1591783200, 'https://www.smashingmagazine.com/2020/06/website-stressing-out-visitors/'),
(756, 'en', 12, 'From Static Sites To End User JAMstack Apps With FaunaDB', 'https://www.smashingmagazine.com/2020/06/static-sites-jamstack-apps-faunadb/', NULL, 'The JAMstack has proven itself to be one of the top ways of producing content-driven sites, but it’s also a great place to house applications, as well. If you’ve been using the JAMstack for your performant websites, the demos in this article will help you extend those philosophies to applications as well.\nWhen using the JAMstack to build applications, you need a data service that fits into the most important aspects of the JAMstack philosophy:', 1591704000, 'https://www.smashingmagazine.com/2020/06/static-sites-jamstack-apps-faunadb/'),
(757, 'en', 12, '12 Ways To Improve User Interview Questions', 'https://www.smashingmagazine.com/2020/06/user-interview-questions/', NULL, 'An experienced interviewer takes care of many things: builds hypotheses, selects interviewees, composes invitations, schedules appointments, sets the stage, and, of course, writes an interview script. Any of these preparations can go wrong, but the script failure means all the effort is in vain. So, if you haven’t interviewed people a lot before or you have to delegate it to non-designers, I’d recommend paying attention to high-quality questions, in the first place.', 1591698600, 'https://www.smashingmagazine.com/2020/06/user-interview-questions/'),
(758, 'en', 12, 'Higher-Order Components In React', 'https://www.smashingmagazine.com/2020/06/higher-order-components-react/', NULL, 'Higher-order components (HOCs) in React were inspired by higher-order functions in JavaScript. A HOC is an advanced technique for reusing logic in React components. It is a pattern created out of React’s compositional nature.\nHOCs basically incorporate the don’t-repeat-yourself (DRY) principle of programming, which you’ve most likely come across at some point in your career as a software developer. It is one of the best-known principles of software development, and observing it is very important when building an application or writing code in general.', 1591617600, 'https://www.smashingmagazine.com/2020/06/higher-order-components-react/'),
(759, 'en', 12, 'Equivalent Experiences: Thinking Equivalently', 'https://www.smashingmagazine.com/2020/06/equivalent-experiences-part2/', NULL, 'This is the second of two articles on the topic of how digital accessibility is informed by equivalency. Previously, we have learned about the underlying biases that inform digital product creation, what isn’t an equivalent experience, the compounding effects of inaccessible design and code, and powerful motivating forces for doing better.\nIn this article, I will discuss learning how to embrace an equivalent, inclusive mindset. I will also provide practical, robust ways to improve your websites and web apps by providing solutions to common, everyday barriers cited by the people I interviewed.', 1591358400, 'https://www.smashingmagazine.com/2020/06/equivalent-experiences-part2/'),
(760, 'en', 12, '#BlackLivesMatter', 'https://www.smashingmagazine.com/2020/06/black-lives-matter/', NULL, 'Contributing to positive change is difficult, but it’s the right pursuit, no matter how much effort it takes. For years here at Smashing, we’ve been working with our dear authors and speakers, as well as students and professionals around the world, to share insights and practical techniques to work better and faster. We’re very much committed to that mission, and it’s always an incredible feeling to meet somebody who has read one of our articles, or attended one of our workshops, who still remembers their experience as that one little step that helped progress their career as a result.', 1591264800, 'https://www.smashingmagazine.com/2020/06/black-lives-matter/'),
(761, 'en', 12, 'How To Test A Design Concept For Effectiveness', 'https://www.smashingmagazine.com/2020/06/test-design-concept-effectiveness/', NULL, 'Most of us are reasonably comfortable with the idea of carrying out usability testing on a website or prototype. We don’t always get the opportunity, but most people accept that it is a good idea.\nHowever, when it comes to a design concept, opinion is more divided. Some designers feel it undermines their role, a view that seems to be somewhat backed up by the famous “Forty Shades of Blue” episode, where Google tested which one of forty shades of blue to use for link color.', 1591263000, 'https://www.smashingmagazine.com/2020/06/test-design-concept-effectiveness/'),
(762, 'en', 12, 'Consuming REST APIs In React With Fetch And Axios', 'https://www.smashingmagazine.com/2020/06/rest-api-react-fetch-axios/', NULL, 'Consuming REST APIs in a React Application can be done in various ways, but in this tutorial, we will be discussing how we can consume REST APIs using two of the most popular methods known as Axios (a promise-based HTTP client) and Fetch API (a browser in-built web API). I will discuss and implement each of these methods in detail and shed light on some of the cool features each of them have to offer.', 1591180200, 'https://www.smashingmagazine.com/2020/06/rest-api-react-fetch-axios/'),
(763, 'en', 12, 'Click! Here: Meet Our New Smashing Book', 'https://www.smashingmagazine.com/2020/06/encouraging-clicks-book-release/', NULL, 'You’ve been there before, haven’t you? Perhaps your manager insists on using a dark pattern to trick customers into buying. Or an A/B test has just shown that an annoying pop-up does increase sign-ups. Or maybe you always end up firefighting negative reviews and angry customer inquiries and your calls to action don’t perform well.\nWhether we are designers, marketers, entrepreneurs, or product owners, we are all in the same boat.', 1591099200, 'https://www.smashingmagazine.com/2020/06/encouraging-clicks-book-release/'),
(764, 'en', 12, 'Smashing Podcast Episode 17 With Angie Byron: What’s New In Drupal 9?', 'https://www.smashingmagazine.com/2020/06/smashing-podcast-episode-17/', NULL, 'In this episode of the Smashing Podcast, we’re taking a look at what’s new in Drupal 9. What are the major upcoming changes to this nearly 20-year-old open-source project? Drew McLellan talks to Drupal core committer Angie Byron to find out.\nShow Notes Angie Byron on Twitter and her personal website Angie works for Acquia who build software and services around Drupal Drupal and About Drupal 9 Weekly Update “How To Feel More Energized Even When You’re Stuck At A Desk All Day”', 1591074000, 'https://www.smashingmagazine.com/2020/06/smashing-podcast-episode-17/'),
(765, 'en', 12, 'React Error Handling And Reporting With Error Boundary And Sentry', 'https://www.smashingmagazine.com/2020/06/react-error-handling-reporting-error-boundary-sentry/', NULL, 'In this article, we’ll look at error boundaries in React. We’ll learn what they are and how to use them to deliver a better user experience, even when something breaks in our app. We’ll also learn how to integrate with Sentry for realtime error monitoring.\nThis tutorial is aimed at React developers of every level who wants to start using error boundaries in their react apps.\nThe only prerequisite is that you have some familiarity with React class components.', 1591012800, 'https://www.smashingmagazine.com/2020/06/react-error-handling-reporting-error-boundary-sentry/'),
(766, 'en', 12, 'Explore Your Inner Artist (June 2020 Wallpapers Edition)', 'https://www.smashingmagazine.com/2020/05/desktop-wallpaper-calendars-june-2020/', NULL, 'There’s an artist in everyone. Some bring their creative ideas to life with digital tools, others capture the perfect moment with a camera or love to grab pen and paper to create little doodles or pieces of lettering. And even if you think you’re far away from being an artist, well, it might just be buried somewhere deep inside of you. So why not explore it?\nSince more than nine years already, our monthly wallpapers challenge is the perfect opportunity to do just that: to challenge your creative skills and break out of your routine of meeting deadlines and client expectations for a moment to do something just for fun.', 1590904800, 'https://www.smashingmagazine.com/2020/05/desktop-wallpaper-calendars-june-2020/'),
(767, 'en', 12, 'Smashing Meets Gives A Sneak Preview Of What To Expect At Live!', 'https://www.smashingmagazine.com/2020/05/smashing-meets-live/', NULL, 'Last week we had our first Smashing Meets event. A free event across two days and many timezones, with three speakers each day and plenty of chance for attendees to chat and ask questions of the speakers. In addition to brightening your day with a virtual meetup, Meets was a chance for us to test the conference platform we’ll be using for our first Smashing Live conference. So, how did it go?', 1590753600, 'https://www.smashingmagazine.com/2020/05/smashing-meets-live/'),
(768, 'en', 12, 'Mirage JS Deep Dive: Understanding Factories, Fixtures And Serializers (Part 2)', 'https://www.smashingmagazine.com/2020/05/mirage-javascript-factories-fixtures-serializers/', NULL, 'In the previous article of this series, we understudied Models and Associations as they relate to Mirage. I explained that Models allow us to create dynamic mock data that Mirage would serve to our application when it makes a request to our mock endpoints. In this article, we will look at three other Mirage features that allow for even more rapid API mocking. Let’s dive right in!\nNote: I highly recommend reading my first two articles if you haven’t to get a really solid handle on what would be discussed here.', 1590750000, 'https://www.smashingmagazine.com/2020/05/mirage-javascript-factories-fixtures-serializers/'),
(769, 'en', 13, 'Creative Background Patterns Using Gradients, CSS Shapes, and Even Emojis', 'https://css-tricks.com/creative-background-patterns-using-gradients-css-shapes-and-even-emojis/', 'Preethi', '<p>You can <a href=\"https://css-tricks.com/stripes-css/\">create stripes in CSS</a>. That’s all I thought about in terms of CSS background patterns for a long time. There’s nothing wrong with stripes; stripes are cool. They can be customized into wide and narrow bands, criss-crossed into a checked pattern, and played with in other ways using <a href=\"https://css-tricks.com/books/greatest-css-tricks/hard-stop-gradients/\">the idea of hard stops</a>. But stripes can be boring, too. Too conventional, out of fashion, and sometimes even unpleasant.</p>\n<p>Thankfully, we can conjure up far more background &#8230; <a href=\"https://css-tricks.com/creative-background-patterns-using-gradients-css-shapes-and-even-emojis/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;Creative Background Patterns Using Gradients, CSS Shapes, and Even Emojis&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/creative-background-patterns-using-gradients-css-shapes-and-even-emojis/\">Creative Background Patterns Using Gradients, CSS Shapes, and Even Emojis</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1591800325, 'https://css-tricks.com/?p=312443'),
(770, 'en', 13, 'CSS :is() and :where() are coming to browsers', 'https://webplatform.news/issues/2020-06-04', 'Chris Coyier', '<p>Šime Vidas with the lowdown on what these pseudo-selectors are and why they will be useful:</p>\n<ul>\n<li><code>:is()</code> is to reduce repetition<a href=\"#fn:1\">¹</a> of parts of comma-separated selectors. </li>\n<li><code>:where()</code> is the same, but nothing inside it affects specificity. The example of wrapping <code>:where(:not())</code> is really great, as now there is a way to use <code>:not()</code> without bumping up the selector weight in a way you very likely don&#8217;t want.</li>\n</ul>\n<ol>\n<li>This is something that CSS preprocessors are good at (via nesting). Another </li>\n</ol>\n<p>&#8230; <a href=\"https://css-tricks.com/css-is-and-where-are-coming-to-browsers/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;CSS :is() and :where() are coming to browsers&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/css-is-and-where-are-coming-to-browsers/\">CSS :is() and :where() are coming to browsers</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1591800300, 'https://css-tricks.com/?p=312524'),
(771, 'en', 13, 'Cool Little CSS Grid Tricks for Your Blog', 'https://css-tricks.com/cool-little-css-grid-tricks-for-your-blog/', 'Ana Tudor', '<p>I discovered CSS about a decade ago while trying to modify the look of a blog I had created. Pretty soon, I was able to code <a href=\"https://codepen.io/thebabydino/details/GRgYQge\">cool things</a> with more mathematical and, therefore, easier-to-understand features like transforms. However, other areas of CSS, such as layout, have remained a constant source of pain.</p>\n<p>This post is about a problem I encountered about a decade ago and, until recently, did not know how to solve in a smart way. Specifically, it&#8217;s about &#8230; <a href=\"https://css-tricks.com/cool-little-css-grid-tricks-for-your-blog/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;Cool Little CSS Grid Tricks for Your Blog&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/cool-little-css-grid-tricks-for-your-blog/\">Cool Little CSS Grid Tricks for Your Blog</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1591740000, 'https://css-tricks.com/?p=311528'),
(772, 'en', 13, 'Making My Netlify Build Run Sass', 'https://css-tricks.com/making-my-netlify-build-run-sass/', 'Chris Coyier', '<p>Let&#8217;s say you wanted to build a site with <a href=\"https://www.11ty.dev/\">Eleventy</a> as the generator. Popular choice these days! Eleventy doesn&#8217;t have some particularly blessed way of preprocessing your CSS, if that&#8217;s something you want to do. There are a variety of ways to do it and perhaps that freedom is part of the spirit of Eleventy.</p>\n<p>I&#8217;ve seen people set up Gulp for this, which is cool, I still use and like Gulp for some stuff. I&#8217;ve seen someone use <a href=\"https://dev.to/adamkdean/simple-scss-with-11ty-kmn\">templating</a>&#8230; <a href=\"https://css-tricks.com/making-my-netlify-build-run-sass/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;Making My Netlify Build Run Sass&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/making-my-netlify-build-run-sass/\">Making My Netlify Build Run Sass</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1591715402, 'https://css-tricks.com/?p=312530'),
(773, 'en', 13, '5 Myths About Jamstack', 'https://css-tricks.com/5-myths-about-jamstack/', 'Brian Rinaldi', '<p>Jamstack isn&#8217;t necessarily new. The term was officially coined in 2016, but the technologies and architecture it describes have been around well before that. Jamstack has received a massive dose of attention recently, with articles about it appearing in major sites and publications and new Jamstack-focused <a href=\"https://jamstackconf.com/\">events</a>, <a href=\"https://jamstack.email/\">newsletters</a>, <a href=\"https://thatsmyjamstack.com/\">podcasts</a>, and more. As someone who follows it closely, I&#8217;ve even seen what seems like a significant uptick in discussion about it on Twitter, often from people who are &#8230; <a href=\"https://css-tricks.com/5-myths-about-jamstack/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;5 Myths About Jamstack&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/5-myths-about-jamstack/\">5 Myths About Jamstack</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1591714263, 'https://css-tricks.com/?p=310812'),
(774, 'en', 13, 'The Trickery it Takes to Create eBook-Like Text Columns', 'https://css-tricks.com/the-trickery-it-takes-to-create-ebook-like-text-columns/', 'Chris Coyier', '<p>There&#8217;s some interesting CSS trickery in Jason Pamental&#8217;s <a href=\"https://mailchi.mp/2bbe439266f6/web-typography-news-47-on-the-nature-of-book-ishness\">latest Web Fonts &#38; Typography News</a>. Jason wanted to bring swipeable columns to his <a href=\"https://mobydick.wales/\">digital book experience</a> on mobile. Which brings up an interesting question right away&#8230; <em>how do you set full-width columns that add columns horizontally, as-needed ? </em>Well that&#8217;s a good trick right there, and it&#8217;s a one-liner:</p>\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"\"><code markup=\"tt\">columns: 100vw auto;</code></pre>\n<p>But it gets more complicated and disappointing from there.</p>\n<p>With just a smidge more formatting to the columns:&#8230; <a href=\"https://css-tricks.com/the-trickery-it-takes-to-create-ebook-like-text-columns/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;The Trickery it Takes to Create eBook-Like Text Columns&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/the-trickery-it-takes-to-create-ebook-like-text-columns/\">The Trickery it Takes to Create eBook-Like Text Columns</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1591651386, 'https://css-tricks.com/?p=312174'),
(775, 'en', 13, 'How to Get All Custom Properties on a Page in JavaScript', 'https://css-tricks.com/how-to-get-all-custom-properties-on-a-page-in-javascript/', 'Tyler Gaw', '<p>We can use JavaScript to get the value of a CSS custom property. Robin wrote up a detailed explanation about this in <a href=\"https://css-tricks.com/get-a-css-custom-property-value-with-javascript/\">Get a CSS Custom Property Value with JavaScript</a>. To review, let’s say we’ve declared a single custom property on the HTML element:</p>\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"\"><code markup=\"tt\">html {\n  --color-accent: #00eb9b;\n}</code></pre>\n<p>In JavaScript, we can access the value with <code>getComputedStyle</code> and <code>getPropertyValue</code>:</p>\n<pre rel=\"JavaScript\" class=\"wp-block-csstricks-code-block language-javascript\" data-line=\"\"><code markup=\"tt\">const colorAccent = getComputedStyle(document.documentElement)\n  .getPropertyValue(\'--color-accent\'); // #00eb9b</code></pre>\n<p>Perfect. Now we have access to our accent color in JavaScript. &#8230; <a href=\"https://css-tricks.com/how-to-get-all-custom-properties-on-a-page-in-javascript/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;How to Get All Custom Properties on a Page in JavaScript&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/how-to-get-all-custom-properties-on-a-page-in-javascript/\">How to Get All Custom Properties on a Page in JavaScript</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1591625593, 'https://css-tricks.com/?p=311697'),
(776, 'en', 13, 'Analyzing Notion app performance', 'https://3perf.com/blog/notion/', 'Robin Rendle', '<p>Here’s a fantastic case study where Ivan Akulov looks at the rather popular writing app Notion and how the team might improve the performance in a variety of ways; through code splitting, removing unused vendor code, module concatenation, and deferring JavaScript execution. Not so long ago, we made a list for <a href=\"https://css-tricks.com/web-performance-checklist/\">getting started with web performance</a> but this article goes so much further into the app side of things: making sure that users are loading only the JavaScript that they &#8230; <a href=\"https://css-tricks.com/analyzing-notion-app-performance/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;Analyzing Notion app performance&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/analyzing-notion-app-performance/\">Analyzing Notion app performance</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1591625560, 'https://css-tricks.com/?p=312407'),
(777, 'en', 13, 'Diverse Illustration', 'https://css-tricks.com/diverse-illustration/', 'Chris Coyier', '<p>Hey gang, <a href=\"https://blacklivesmatter.com/\">#BlackLivesMatter</a>. </p>\n<p>One tiny way I thought we could help here on this site, aside from our efforts as individuals, is to highlight some design resources that are both excellent and feature Black people. <a href=\"https://www.pbs.org/newshour/arts/why-on-screen-representation-matters-according-to-these-teens\">Representation matters.</a></p>\n<p>Here&#8217;s one. You know <a href=\"https://twitter.com/pablostanley\">Pablo Stanley</a>? Pablo is a wonderful illustrator who combines his illustration work with modern design tooling. He has these illustration libraries that come as Sketch and Figma plugins so you can mix and match characters and their &#8230; <a href=\"https://css-tricks.com/diverse-illustration/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;Diverse Illustration&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/diverse-illustration/\">Diverse Illustration</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1591538210, 'https://css-tricks.com/?p=312476'),
(778, 'en', 13, 'How I Used Brotli to Get Even Smaller CSS and JavaScript Files at CDN Scale', 'https://css-tricks.com/how-i-used-brotli-to-get-even-smaller-css-and-javascript-files-at-cdn-scale/', 'Hamid Sarfraz', '<p>This article is about my experience using Brotli at production scale. Despite being really expensive and a truly unfeasible method for on-the-fly compression, Brotli is actually very economical and saves cost on many fronts, especially when compared with gzip or lower compression levels of Brotli.</p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/how-i-used-brotli-to-get-even-smaller-css-and-javascript-files-at-cdn-scale/\">How I Used Brotli to Get Even Smaller CSS and JavaScript Files at CDN Scale</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1591368593, 'https://css-tricks.com/?p=311500'),
(795, 'en', 10, 'Kotlin Coroutines and Delay', 'http://feedproxy.google.com/~r/Bludice/~3/AtYn74mMHEo/kotlin-coroutines', 'David Walsh', '<p>Whenever I suspect that there&#8217;s a timing conflict causing a problem with rendering and directives, I usually opt for a JavaScript setTimeout with a delay. The setTimeout code never makes it to production, but it does help me to understand if my code is the problem or if there&#8217;s a timing conflict. In working with [&#8230;]</p>\n<p>The post <a rel=\"nofollow\" href=\"https://davidwalsh.name/kotlin-coroutines\">Kotlin Coroutines and Delay</a> appeared first on <a rel=\"nofollow\" href=\"https://davidwalsh.name\">David Walsh Blog</a>.</p>\n<p><a href=\"https://tkjs.us/dwb\"><img style=\"margin:0 auto\" alt=\"\" src=\"https://davidwalsh.name/demo/tjs_block-1.svg\"></a></p>\n', 1591843536, 'https://davidwalsh.name/?p=27147'),
(796, 'en', 12, 'Building A Facial Recognition Web Application With React', 'https://www.smashingmagazine.com/2020/06/facial-recognition-web-application-react/', NULL, 'If you are going to build a facial recognition web app, this article will introduce you to an easy way of integrating such. In this article, we will take a look at the Face Detection model and Predict API for our face recognition web app with React.\nWhat Is Facial Recognition And Why Is It Important? Facial recognition is a technology that involves classifying and recognizing human faces, mostly by mapping individual facial features and recording the unique ratio mathematically and storing the data as a face print.', 1591869600, 'https://www.smashingmagazine.com/2020/06/facial-recognition-web-application-react/'),
(797, 'en', 13, 'CUBE CSS', 'https://piccalil.li/blog/cube-css/', 'Chris Coyier', '<p><a href=\"https://piccalil.li/blog/cube-css/\">A CSS methodology</a> from Andy Bell:</p>\n<blockquote class=\"wp-block-quote\">\n<p>The most important part of this methodology is the language itself: CSS. It’s key to note its existence in the name because some alternative approaches, such as <a href=\"https://css-tricks.com/bem-101/\">BEM</a>—which I have enjoyed for many years—can veer very far away from Cascading Style Sheets. I <em>love</em> CSS, though and think that its core capabilities are actually <strong>key</strong> to scalable CSS.</p>\n</blockquote>\n<p>A favorite bit&#8230;</p>\n<blockquote class=\"wp-block-quote\">\n<p>[&#8230;] a design system doesn’t just make you think at a <strong>micro-level</strong></p>\n</blockquote>\n<p>&#8230; <a href=\"https://css-tricks.com/cube-css/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;CUBE CSS&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/cube-css/\">CUBE CSS</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1591909146, 'https://css-tricks.com/?p=312696'),
(798, 'en', 13, 'On Adding IDs to Headings', 'https://css-tricks.com/on-adding-ids-to-headers/', 'Chris Coyier', '<p>Here&#8217;s a two-second review. If an element has an ID, you can link to it with natural browser behavior. It&#8217;s great if headings have them, because it&#8217;s often useful to link directly to a specific section of content.</p>\n<pre rel=\"HTML\" class=\"wp-block-csstricks-code-block language-markup\" data-line=\"\"><code markup=\"tt\">&#60;h3 id=\"step-2\"Step 2&#60;/a</code></pre>\n<p>Should I be so inclined, I could link right to this heading, be it from an URL, like <code>https://my-website.com/#step-2</code>, or an on-page link, like:</p>\n<pre rel=\"HTML\" class=\"wp-block-csstricks-code-block language-markup\" data-line=\"\"><code markup=\"tt\">&#60;a href=\"#step-2\"Jump to Step 2&#60;/a</code></pre>\n<p>So, it&#8217;s ideal if all headers have &#8230; <a href=\"https://css-tricks.com/on-adding-ids-to-headers/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;On Adding IDs to Headings&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/on-adding-ids-to-headers/\">On Adding IDs to Headings</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1591908479, 'https://css-tricks.com/?p=312635'),
(799, 'en', 13, 'How to Reverse CSS Custom Counters', 'https://css-tricks.com/how-to-reverse-css-custom-counters/', 'Etinosa Obaseki', '<p>I needed a numbered list of blog posts to be listed with the last/high first and going down from there. Like this:</p>\n<pre rel=\"HTML\" class=\"wp-block-csstricks-code-block language-markup\" data-line=\"\"><code markup=\"tt\">5. Post Title\n4. Post Title\n3. Post Title\n2. Post Title\n1. Post Title</code></pre>\n<p>But the above is just text. I wanted to do this with a semantic <code>&#60;ol&#62;</code> element.</p>\n<p>The easy way</p>\n<p>This can be done using HTML&#8217; s <code>reversed</code> property on the <code>&#60;ol&#62;</code>:</p>\n<pre rel=\"HTML\" class=\"wp-block-csstricks-code-block language-markup\" data-line=\"1\"><code markup=\"tt\">&#60;ol reversed&#60;liThis&#60;/li&#60;liList&#60;/li&#60;liWill Be&#60;/li&#60;liNumbered </code></pre>\n<p>&#8230; <a href=\"https://css-tricks.com/how-to-reverse-css-custom-counters/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;How to Reverse CSS Custom Counters&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/how-to-reverse-css-custom-counters/\">How to Reverse CSS Custom Counters</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1591886547, 'https://css-tricks.com/?p=312104'),
(810, 'en', 12, 'Internationalization In Vue With The Vue I18n Plugin', 'https://www.smashingmagazine.com/2020/06/internationalization-vue-i18n/', NULL, 'Building applications for people from different parts of the world comes with challenges like support for multiple locales and how to integrate it into your application. I remember the first time I faced this challenge, I had to build an application that was going to have multiple languages (English, Yoruba, and French). This was the first time I ever wondered how applications that supported multiple languages were built and also how I discovered “Internationalization”.', 1591956000, 'https://www.smashingmagazine.com/2020/06/internationalization-vue-i18n/'),
(811, 'en', 13, 'Striking a Balance Between Native and Custom Select Elements', 'https://css-tricks.com/striking-a-balance-between-native-and-custom-select-elements/', 'Sandrina Pereira', '<p>Here’s the plan! We’re going to build a styled select element. Not just <a href=\"https://css-tricks.com/styling-a-select-like-its-2019/\">the outside</a>, but the inside too. Total styling control. Plus we’re going to make it accessible. We’re not going to try to <em>replicate</em> everything that the browser does by default with a native <code>&#60;select&#62;</code> element. We’re going to literally use a <code>&#60;select&#62;</code> element when any assistive tech is used. But when a mouse is being used, we’ll show the styled version and make it function as &#8230; <a href=\"https://css-tricks.com/striking-a-balance-between-native-and-custom-select-elements/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;Striking a Balance Between Native and Custom Select Elements&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/striking-a-balance-between-native-and-custom-select-elements/\">Striking a Balance Between Native and Custom Select Elements</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1591973012, 'https://css-tricks.com/?p=312544'),
(812, 'en', 13, 'Learn Z-Index Using a Visualization Tool', 'https://thirumanikandan.com/posts/learn-z-index-using-a-visualization-tool', 'Chris Coyier', '<p>There are some neat interactive demos <a href=\"https://thirumanikandan.com/posts/learn-z-index-using-a-visualization-tool\">in here</a> from Thiru Manikandan. There are a couple of very tricky things with <code><a href=\"https://css-tricks.com/almanac/properties/z/z-index/\">z-index</a></code> that never fail to confuse. In addition to things like requiring positioning and source order, the trickiest are the stacking contexts and parent/child relationships. <code>z-index</code> isn&#8217;t a flat playing field. Even if you put <code>z-index: 2147483644</code><a href=\"#fn:1\">¹</a> on an element, it&#8217;s possible nothing will happen because that element might be inside a parent element with its own stacking context &#8230; <a href=\"https://css-tricks.com/learn-z-index-using-a-visualization-tool/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;Learn Z-Index Using a Visualization Tool&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/learn-z-index-using-a-visualization-tool/\">Learn Z-Index Using a Visualization Tool</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1591973002, 'https://css-tricks.com/?p=312701'),
(839, 'en', 12, 'Which Video Conferencing Tools Are Most Accessible?', 'https://www.smashingmagazine.com/2020/06/accessible-video-conferencing-tools/', NULL, 'With us all suddenly working from home in the COVID era, most of us have had to make some quick choices from a huge variety of video conferencing and collaboration tools. But do all of these apps work well for everyone? If you have a co-worker or a student with a disability, would they be able to participate as well?\nIf you’ve had a disability yourself &mdash; or if you work in government or higher education &mdash; you’ve probably faced this question already.', 1592224200, 'https://www.smashingmagazine.com/2020/06/accessible-video-conferencing-tools/'),
(840, 'en', 13, 'My Flywheel Landing Page', 'https://css-tricks.com/my-flywheel-landing-page/', 'Chris Coyier', '<p><a href=\"https://share.getf.ly/k96n2f\">Flywheel</a> is my WordPress hosting partner here. I <a href=\"https://css-tricks.com/local-by-flywheel/\">use Local</a> every day for my WordPress local development environment and use their hosting for all my WordPress sites as part of my <a href=\"https://css-tricks.com/video-screencasts/177-local-wordpress-development-to-production-workflow/\">whole flow</a>, so I&#8217;m glad they aren&#8217;t just a sponsor but a product I use and like.</p>\n<p>Last November some of their crew came out and shot some photos and video with me, which was cool and fun and made me feel famous lolll.</p>\n<p>They ultimately <a href=\"https://getflywheel.com/chris-coyier/\">built a </a>&#8230; <a href=\"https://css-tricks.com/my-flywheel-landing-page/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;My Flywheel Landing Page&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/my-flywheel-landing-page/\">My Flywheel Landing Page</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1592234078, 'https://css-tricks.com/?p=312954'),
(841, 'en', 13, 'Adding a Custom Welcome Guide to the WordPress Block Editor', 'https://css-tricks.com/adding-a-custom-welcome-guide-to-the-wordpress-block-editor/', 'Leonardo Losoviz', '<p>I am creating a WordPress plugin and there is a slight learning curve when it comes to using it. I’d like to give users a primer on how to use the plugin, but I want to avoid diverting users to documentation on the plugin&#8217;s website since that takes them out of the experience.</p>\n<p>What would be great is for users to immediately start using the plugin once it’s installed but have access to helpful tips while they are actively using &#8230; <a href=\"https://css-tricks.com/adding-a-custom-welcome-guide-to-the-wordpress-block-editor/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;Adding a Custom Welcome Guide to the WordPress Block Editor&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/adding-a-custom-welcome-guide-to-the-wordpress-block-editor/\">Adding a Custom Welcome Guide to the WordPress Block Editor</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1592231868, 'https://css-tricks.com/?p=312604');
INSERT INTO `aggregator_item` (`iid`, `langcode`, `fid`, `title`, `link`, `author`, `description`, `timestamp`, `guid`) VALUES
(842, 'en', 1, 'Le campagne intelligenti aiutano le piccole imprese a raggiungere più clienti', 'http://feedproxy.google.com/~r/GoogleItaliaBlog/~3/nJ8xDJIUpWo/le-campagne-intelligenti-aiutano-le.html', 'Google Press Italia', '<div class=\"separator\" style=\"clear: both; text-align: center;\"><br /></div><span id=\"docs-internal-guid-93a96598-7fff-1fd6-dc2b-22213958a6e5\"></span><span data-about-syndication=\"\" style=\"display: none; font-size: 0; line-height: 0; max-height: 0; overflow: hidden;\"> <!--   INSTRUCTIONS   Enter info below to be used in google.com/about site blog syndication. Leave elements empty if there is no valid data.    Example:   <span class=\"post-image\">http://1.bp.blogspot.com/-mX0dxJxp8dg/Vo8MSdxypWI/AAAAAAAARsI/EjaFhvgAEgc/s1600/Beutler_Google_Giftwrap_-v2TW.png</span>  <span class=\"post-author-name\">Abbi Tatton</span>  <span class=\"post-author-title\">Editorial Elf</span>  <span class=\"post-author-team\">Google</span>--> <span class=\"post-image\"></span><span class=\"post-author-name\"></span><span class=\"post-author-title\"></span><span class=\"post-author-team\"></span></span><br /><div class=\"separator\" style=\"clear: both; text-align: center;\"><a href=\"https://1.bp.blogspot.com/-BbSV29_8QM8/XuoD-JILuyI/AAAAAAAAEr4/wiq3s2SpPQQzZYHoMnmQiJi3OEimn_SSACLcBGAsYHQ/s1600/Final_11231_SmartCampaignsKeywordBlog_Hero_universal_05212020.png\" imageanchor=\"1\" style=\"margin-left: 1em; margin-right: 1em;\"><img border=\"0\" data-original-height=\"667\" data-original-width=\"1600\" height=\"266\" src=\"https://1.bp.blogspot.com/-BbSV29_8QM8/XuoD-JILuyI/AAAAAAAAEr4/wiq3s2SpPQQzZYHoMnmQiJi3OEimn_SSACLcBGAsYHQ/s640/Final_11231_SmartCampaignsKeywordBlog_Hero_universal_05212020.png\" width=\"640\" /></a></div><div dir=\"ltr\" style=\"line-height: 1.38; margin-bottom: 0pt; margin-top: 0pt;\"><br /></div>Le piccole imprese sono alla ricerca di strumenti per gestire il proprio business online e raggiungere l\'audience più adatta. Le campagne intelligenti, progettate specificatamente per le piccole imprese, sono una soluzione automatizzata che aiuta a promuovere la propria attività su Google.<br /><br />Abbiamo recentemente reso disponibili le campagne intelligenti di Google Ads in tutti i 150 paesi in cui Google Ads è disponibile. Le imprese di qualunque dimensione possono ora attivare le proprie inserzioni in soli 15 minuti. <br /><br />Inoltre, stiamo semplificando l\'utilizzo delle campagne intelligenti: sono in arrivo nuove funzionalità che aiutano a registrarsi da ogni dispositivo, farsi notare su Google Maps, vedere i propri risultati sulla Ricerca Google e gestire i propri annunci.<br /><b><br /></b><b>Registrarsi direttamente dall\'App mobile</b><br /><b><br /></b>Ora è possibile registrarsi, creare una campagna intelligente e pubblicare le proprie inserzioni direttamente dall\'app Google Ads su <a href=\"https://play.google.com/store/apps/details?id=com.google.android.apps.adwords&amp;referrer=utm_source%3Dsmartcampaignsblog%26utm_medium%3Dblogpost\">Android</a> e <a href=\"https://apps.apple.com/app/apple-store/id1037457231?pt=9008&amp;ct=smartcampaignsblog&amp;mt=8\">iOS</a>. Abbiamo reso questo processo più veloce e più semplice per permettere di iniziare a pubblicare le inserzioni sin da subito. La registrazione attraverso l\'app sarà al momento disponibile in Italia, Stati Uniti, Canada, Australia, Regno Unito, Francia, Spagna, Paesi Bassi e Giappone e seguiranno altri paesi.<br /><div><br /></div><div class=\"separator\" style=\"clear: both; text-align: center;\"><a href=\"https://1.bp.blogspot.com/-MQfTUUw8ti4/XuoFoa2aClI/AAAAAAAAEsE/SIHcGDl-CNgkAXxjUZm7c7yla_OL2o77ACLcBGAsYHQ/s1600/%255BMOBILE%2BSIGNUP%255D.png\" imageanchor=\"1\" style=\"margin-left: 1em; margin-right: 1em;\"><img border=\"0\" data-original-height=\"1600\" data-original-width=\"1600\" height=\"400\" src=\"https://1.bp.blogspot.com/-MQfTUUw8ti4/XuoFoa2aClI/AAAAAAAAEsE/SIHcGDl-CNgkAXxjUZm7c7yla_OL2o77ACLcBGAsYHQ/s400/%255BMOBILE%2BSIGNUP%255D.png\" width=\"398\" /></a></div><div class=\"separator\" style=\"clear: both; text-align: center;\"><br /></div><b>Vi aiutiamo a farvi notare su Google Maps, gratuitamente</b><br /><b><br /></b>Ogni mese sono più di un miliardo le persone che utilizzano Google Maps per osservare che cosa c’è intorno a loro, cercare le imprese e ottenere indicazioni. I promoted pin (segnaposto sponsorizzati) su Google Maps aiuteranno la vostra attività a farsi notare grazie a un segnaposto visibile e di forma quadrata. <br /><br />Dal momento che è di nuovo possibile visitare le diverse attività di persona, vorremmo aiutarvi a indirizzare un numero maggiore clienti verso di voi. Per questo motivo, fino a settembre 2020, non verrà addebitato nessun importo per i click, le chiamate o le vendite derivati dai promoted pin.<br /><div><span id=\"docs-internal-guid-d51a61a5-7fff-fc9d-afd4-1c4865b5a5b2\"><span style=\"color: #1155cc; font-family: &quot;google sans&quot; , sans-serif; font-size: 10pt; vertical-align: baseline; white-space: pre-wrap;\"></span></span></div><div><br /></div><div class=\"separator\" style=\"clear: both; text-align: center;\"><a href=\"https://1.bp.blogspot.com/-OSFcctjUe7k/XuoGhDPZxrI/AAAAAAAAEsc/gmsVkaT2x2UlM_2at3U_jUc5Ny_kKN9zgCLcBGAsYHQ/s1600/SC-Squarepins-Flow3%2B%25282%2529.gif\" imageanchor=\"1\" style=\"margin-left: 1em; margin-right: 1em;\"><img border=\"0\" data-original-height=\"1600\" data-original-width=\"1600\" height=\"320\" src=\"https://1.bp.blogspot.com/-OSFcctjUe7k/XuoGhDPZxrI/AAAAAAAAEsc/gmsVkaT2x2UlM_2at3U_jUc5Ny_kKN9zgCLcBGAsYHQ/s320/SC-Squarepins-Flow3%2B%25282%2529.gif\" width=\"320\" /></a></div><div class=\"separator\" style=\"clear: both; text-align: center;\"><br /></div><div class=\"separator\" style=\"clear: both; text-align: center;\"><br /></div><b>Controllare le inserzioni e le performance direttamente su Google.com</b><br /><b><br /></b>Se state utilizzando le campagne intelligenti e volete controllare in modo rapido lo stato delle vostre inserzioni, questa funzionalità è adatta a voi. Abbiamo reso le funzionalità di resoconto più accessibili: attraverso una rapida ricerca è possibile verificare in tempo reale lo stato delle campagne intelligenti, il loro andamento e come i potenziali clienti visualizzano le vostre inserzioni. Basterà accedere dall\'account Google che utilizzate per Google Ads ed effettuare la ricerca \"I miei annunci\" o \"Google Ads\" su Google.com<br /><br />Questa funzionalità sarà resa disponibile per tutti gli inserzionisti delle campagne intelligenti nelle prossime settimane.<br /><div class=\"separator\" style=\"clear: both; text-align: center;\"><a href=\"https://1.bp.blogspot.com/-spTIQ-c2n-s/XuoF3sEr2ZI/AAAAAAAAEsQ/CjYP0yi4wuUO0Meg1Sypj7HcuawMJGgwgCLcBGAsYHQ/s1600/%255BMY%2BADS%255D.png\" imageanchor=\"1\" style=\"margin-left: 1em; margin-right: 1em; text-align: center;\"><img border=\"0\" data-original-height=\"1600\" data-original-width=\"1600\" height=\"400\" src=\"https://1.bp.blogspot.com/-spTIQ-c2n-s/XuoF3sEr2ZI/AAAAAAAAEsQ/CjYP0yi4wuUO0Meg1Sypj7HcuawMJGgwgCLcBGAsYHQ/s400/%255BMY%2BADS%255D.png\" width=\"400\" /></a></div><br /><br /><b>Più controllo su quando vengono mostrati gli annunci</b><br /><b><br /></b>Abbiamo notato che le piccole imprese vorrebbero più controllo sulle parole chiave che le aiutano a raggiungere potenziali clienti su Ricerca Google. Con i temi delle parole chiave (precedentemente \"prodotti e servizi\") potete comunicarci che cosa offre la vostra impresa e noi mostreremo le vostre inserzioni ai potenziali clienti che ricercano frasi correlate. Questo significa che le vostre inserzioni potranno raggiungere più persone e voi potrete risparmiare tempo nel processo. Avrete anche la possibilità di modificare o eliminare i temi delle parole chiave, per averne sempre il controllo.<br /><br />I temi delle parole chiave saranno disponibili per tutti gli utilizzatori delle campagne intelligenti nelle prossime settimane.<br /><div><br /></div><div class=\"separator\" style=\"clear: both; text-align: center;\"><a href=\"https://1.bp.blogspot.com/-jWOlxQoJfms/XuoGxJ9KjiI/AAAAAAAAEsg/4Ug_UU8KYDwxGAxNNzdGwDm5PV5wZzPogCLcBGAsYHQ/s1600/Updated_Keyword%2Bthemes_no%2Bwhite%2Bspace.png\" imageanchor=\"1\" style=\"margin-left: 1em; margin-right: 1em;\"><img border=\"0\" data-original-height=\"1136\" data-original-width=\"1600\" height=\"283\" src=\"https://1.bp.blogspot.com/-jWOlxQoJfms/XuoGxJ9KjiI/AAAAAAAAEsg/4Ug_UU8KYDwxGAxNNzdGwDm5PV5wZzPogCLcBGAsYHQ/s400/Updated_Keyword%2Bthemes_no%2Bwhite%2Bspace.png\" width=\"400\" /></a></div><div class=\"separator\" style=\"clear: both; text-align: center;\"><br /></div><br />Per iniziare a sperimentare queste nuove funzionalità potete effettuare l\'accesso con il vostro account Google Ads o iniziare a utilizzare le <a href=\"https://ads.google.com/home/?subid=ww-ww-et-g-aw-a-sc_blogpost!o2\">campagne intelligenti</a>.<br /><br /><span style=\"color: #999999;\">Scritto da: Kim Spalding, Director of Product Management, Google Ads</span><div class=\"feedflare\">\n<a href=\"http://feeds.feedburner.com/~ff/GoogleItaliaBlog?a=nJ8xDJIUpWo:waf0l6DAnHs:yIl2AUoC8zA\"><img src=\"http://feeds.feedburner.com/~ff/GoogleItaliaBlog?d=yIl2AUoC8zA\" border=\"0\"></img></a> <a href=\"http://feeds.feedburner.com/~ff/GoogleItaliaBlog?a=nJ8xDJIUpWo:waf0l6DAnHs:V_sGLiPBpWU\"><img src=\"http://feeds.feedburner.com/~ff/GoogleItaliaBlog?i=nJ8xDJIUpWo:waf0l6DAnHs:V_sGLiPBpWU\" border=\"0\"></img></a>\n</div><img src=\"http://feeds.feedburner.com/~r/GoogleItaliaBlog/~4/nJ8xDJIUpWo\" height=\"1\" width=\"1\" alt=\"\"/>', 1592401556, 'tag:blogger.com,1999:blog-12671138.post-2686620802237302721'),
(843, 'en', 1, 'Google Meet: videoconferenze da Gmail anche su smartphone ', 'http://feedproxy.google.com/~r/GoogleItaliaBlog/~3/elyU3wuN6kI/google-meet-videoconferenze-da-gmail.html', 'Google Press Italia', '<span id=\"docs-internal-guid-ec7d55b2-7fff-fc0e-6329-bab92674be0f\"></span><span data-about-syndication=\"\" style=\"display: none; font-size: 0; line-height: 0; max-height: 0; overflow: hidden;\"> <!--   INSTRUCTIONS   Enter info below to be used in google.com/about site blog syndication. Leave elements empty if there is no valid data.    Example:   <span class=\"post-image\">http://1.bp.blogspot.com/-mX0dxJxp8dg/Vo8MSdxypWI/AAAAAAAARsI/EjaFhvgAEgc/s1600/Beutler_Google_Giftwrap_-v2TW.png</span>  <span class=\"post-author-name\">Abbi Tatton</span>  <span class=\"post-author-title\">Editorial Elf</span>  <span class=\"post-author-team\">Google</span>--> <span class=\"post-image\"></span><span class=\"post-author-name\"></span><span class=\"post-author-title\"></span><span class=\"post-author-team\"></span></span><br /><div><br /></div><div class=\"separator\" style=\"clear: both; text-align: center;\"><a href=\"https://1.bp.blogspot.com/-70Q2V9EHgCs/Xujb3hFvkEI/AAAAAAAAEro/Jj7NyCYZ2lUD5kpOgYqFAff4ndz4PuL8QCLcBGAsYHQ/s1600/Meet_In_Gmail_Mobile_Blog_Header.gif\" imageanchor=\"1\" style=\"margin-left: 1em; margin-right: 1em;\"><img border=\"0\" data-original-height=\"667\" data-original-width=\"1600\" height=\"265\" src=\"https://1.bp.blogspot.com/-70Q2V9EHgCs/Xujb3hFvkEI/AAAAAAAAEro/Jj7NyCYZ2lUD5kpOgYqFAff4ndz4PuL8QCLcBGAsYHQ/s640/Meet_In_Gmail_Mobile_Blog_Header.gif\" width=\"640\" /></a></div><div><br /></div><div><br /></div><div>Gli incontri video sono diventati parte integrante della nostra vita. Dal mese scorso Google Meet, il nostro prodotto premium per le videoconferenze, è diventato&nbsp;<a href=\"https://italia.googleblog.com/2020/05/con-google-meet-ora-le-videoconferenze.html\">gratuito e disponibile per tutti</a>&nbsp;e accessibile direttamente da Gmail da web. Ora Google Meet diventerà disponibile anche su Gmail per Android e iOS, per partecipare alle videoconferenze direttamente dalla casella di posta elettronica del proprio smartphone.</div><div><br /></div><div><span id=\"docs-internal-guid-37431cf6-7fff-7da7-de13-cb706698f85b\"><span style=\"color: #202124; font-family: &quot;Google Sans&quot;, sans-serif; font-size: 11pt; font-variant-east-asian: normal; font-variant-numeric: normal; vertical-align: baseline; white-space: pre-wrap;\"><span style=\"border: none; display: inline-block; height: 437px; overflow: hidden; width: 624px;\"><img height=\"437\" src=\"https://lh4.googleusercontent.com/b7RMW0fuGhIxyJGfHZyDFKf-ETzI_JH-Yd0m7WYJ6FvqAFZEHwswOsjO87KlpyECI9_ezBvnoa1CLv0mHooVUtBlxLuPubY683nz6EiUxYTdVTNFNVWLAM79b0nTgLiuuKapdIvL\" style=\"margin-left: 0px; margin-top: 0px;\" width=\"624\" /></span></span></span></div>Nelle prossime settimane infatti verrà aggiunta una nuova tab Meet sull\'app Gmail su smartphone, grazie alla quale sarà possibile vedere le riunioni pianificate su Google Calendar e prendervi parte facilmente con un solo click. <br /><div><br /></div><div><span id=\"docs-internal-guid-82d41881-7fff-fcbb-803f-2fabce961b16\"><span style=\"color: #202124; font-family: Roboto, sans-serif; font-size: 12pt; font-variant-east-asian: normal; font-variant-numeric: normal; vertical-align: baseline; white-space: pre-wrap;\"><span style=\"border: none; display: inline-block; height: 437px; overflow: hidden; width: 624px;\"><img height=\"437\" src=\"https://lh4.googleusercontent.com/Crx84DTJF9UOzLa-gNClwA96riIS0kKl183qu4HuGmdjBCl25akLgpRS6r5nLz2-_T-SPqBqbbZYN00etOJ-12SLAhZYXxFc9n6o_ZvHxjv5aD4SQETOY58RajGV6ASnkEISm0aj\" style=\"margin-left: 0px; margin-top: 0px;\" width=\"624\" /></span></span></span></div><br />Cliccando su \"Nuova riunione\" nella tab di Meet sarà possibile avviare immediatamente una videoconferenza, oppure ottenere il link alla riunione da condividere o da inserire nel proprio calendario. Cliccando su \"Partecipa con un codice\" ci si potrà collegare alle riunioni a cui si è stati invitati, semplicemente inserendo il codice riunione. <br /><br />Per eliminare la tab di Meet dall\'app Gmail, sarà sufficiente accedere alle impostazioni dal menu nell\'angolo in alto a sinistra della casella di posta, cliccare sul proprio account, scorrere verso il basso e deselezionare Meet. <div><br /></div><div><span id=\"docs-internal-guid-83c3c114-7fff-8cf9-53c4-f8da6c78fc74\"><span style=\"color: #202124; font-family: &quot;Google Sans&quot;, sans-serif; font-size: 11pt; font-variant-east-asian: normal; font-variant-numeric: normal; vertical-align: baseline; white-space: pre-wrap;\"><span style=\"border: none; display: inline-block; height: 437px; overflow: hidden; width: 624px;\"><img height=\"437\" src=\"https://lh6.googleusercontent.com/Osi68n4vJyVtLHqgUzBOdmc5r5deXe5PAmFEk-VQNPd9fU0TXMoQRD6gZPhuzaPf5Ga9O3AK_QXGg8Pk5bV7n-1g-lnqgSGI01GhA7E7bQEGN-GekbxTfo0wDeHBTxoqBC2m5qB7\" style=\"margin-left: 0px; margin-top: 0px;\" width=\"624\" /></span></span></span></div><br /><br />Per saperne di più sull’utilizzo di Meet da Gmail è possibile consultare <a href=\"https://support.google.com/mail/answer/9822902?co=GENIE.Platform%3DiOS&amp;oco=1&amp;hl=it\">questa pratica guida</a>. Maggiori informazioni su Google Meet sono disponibili in&nbsp;<a href=\"https://italia.googleblog.com/2020/04/videoconferenze-premium-con-google-meet.html\">questo articolo</a>. <br /><div><br /></div><span style=\"font-size: x-small;\">Scritto da: Il Team Google Italia</span><div class=\"feedflare\">\n<a href=\"http://feeds.feedburner.com/~ff/GoogleItaliaBlog?a=elyU3wuN6kI:dBoN56LRs04:yIl2AUoC8zA\"><img src=\"http://feeds.feedburner.com/~ff/GoogleItaliaBlog?d=yIl2AUoC8zA\" border=\"0\"></img></a> <a href=\"http://feeds.feedburner.com/~ff/GoogleItaliaBlog?a=elyU3wuN6kI:dBoN56LRs04:V_sGLiPBpWU\"><img src=\"http://feeds.feedburner.com/~ff/GoogleItaliaBlog?i=elyU3wuN6kI:dBoN56LRs04:V_sGLiPBpWU\" border=\"0\"></img></a>\n</div><img src=\"http://feeds.feedburner.com/~r/GoogleItaliaBlog/~4/elyU3wuN6kI\" height=\"1\" width=\"1\" alt=\"\"/>', 1592323871, 'tag:blogger.com,1999:blog-12671138.post-369210638516922897'),
(844, 'en', 1, 'Google vi porta a Interland, un mondo fantastico dove i bambini imparano le basi della sicurezza online divertendosi. ', 'http://feedproxy.google.com/~r/GoogleItaliaBlog/~3/UhQkSEAFvA8/google-vi-porta-interland-un-mondo.html', 'emanuela locci', '<i>Interland si inserisce all’interno del programma “<a href=\"https://beinternetawesome.withgoogle.com/it_it/\">Vivi Internet, al Meglio</a>”, ideato da Google per aiutare ragazzi, famiglie e insegnanti a vivere il mondo online in modo più consapevole.&nbsp;</i><br /><br />Il Web è un luogo straordinario, che ci permette di accedere a informazioni, sviluppare conoscenze e rimanere in contatto con le persone in tutto il mondo. Ma essere bravi cittadini digitali richiede consapevolezza, responsabilità e impegno, tutte cose che non sempre sono immediate per un bambino. Lo sanno bene genitori e docenti, che ogni giorno aiutano i più piccoli a prendere decisioni, essere responsabili e gentili nel mondo online.<br /><br />Con le famiglie che hanno dovuto affrontare la nuove realtà saltando fra lezioni e intrattenimento online e le vacanze estive alle porte, anche i bambini trascorrono più tempo su Internet. Quale momento più adatto per insegnare loro i fondamenti su come vivere la Rete in modo più sicuro? Per aiutarvi in questo percorso oggi presentiamo <a href=\"http://g.co/interland\">Interland</a>, il gioco online interattivo pensato da Google per insegnare ai bambini dai 6 ai 13 anni i fondamenti della sicurezza online in modo divertente e coinvolgente. È gratuito e online, accessibile a tutti all’indirizzo <a href=\"http://g.co/interland,\">g.co/interland,</a> ma soprattutto è in un formato che i bambini amano già. Lo abbiamo creato con l\'aiuto di esperti di sviluppo di sicurezza digitale ed è adatto a tutte le età, con un\'attenzione particolare per i bambini dai 6 ai 13 anni.<br /><table align=\"center\" cellpadding=\"0\" cellspacing=\"0\" class=\"tr-caption-container\" style=\"margin-left: auto; margin-right: auto; text-align: center;\"><tbody><tr><td style=\"text-align: center;\"><a href=\"https://1.bp.blogspot.com/-ihNxdyCKxSk/Xuhq7KZgUTI/AAAAAAAAhM8/_MoRSDK6cXIUf--on0mW6KePbCY-4skwQCNcBGAsYHQ/s1600/Interland%2BHero%2BImage.png\" imageanchor=\"1\" style=\"margin-left: auto; margin-right: auto;\"><img border=\"0\" data-original-height=\"776\" data-original-width=\"1600\" height=\"310\" src=\"https://1.bp.blogspot.com/-ihNxdyCKxSk/Xuhq7KZgUTI/AAAAAAAAhM8/_MoRSDK6cXIUf--on0mW6KePbCY-4skwQCNcBGAsYHQ/s640/Interland%2BHero%2BImage.png\" width=\"640\" /></a></td></tr><tr><td class=\"tr-caption\" style=\"text-align: center;\">L\'ingresso nel mondo di Interland.</td></tr></tbody></table>Interland è un mondo immaginario composto da 4 territori in cui i bambini devono fronteggiare hacker, phisher, chiacchieroni e bulli, esercitando le abilità necessarie per essere bravi cittadini digitali.<br /><br />Attraversando il Fiume della realtà, che scorre a Interland tra realtà e finzioni, i bambini imparano a non cadere nelle trappole del web.<br /><br /><div class=\"separator\" style=\"clear: both; text-align: center;\"><a href=\"https://1.bp.blogspot.com/-QKXyo-ssbu8/Xuhre7ll47I/AAAAAAAAhNE/KZH4GhEEm6QPcFCIRHux2-oKdUllTSF4wCNcBGAsYHQ/s1600/Fiume%2Bdella%2Brealta%25CC%2580.png\" imageanchor=\"1\" style=\"margin-left: 1em; margin-right: 1em;\"><img border=\"0\" data-original-height=\"776\" data-original-width=\"1600\" height=\"310\" src=\"https://1.bp.blogspot.com/-QKXyo-ssbu8/Xuhre7ll47I/AAAAAAAAhNE/KZH4GhEEm6QPcFCIRHux2-oKdUllTSF4wCNcBGAsYHQ/s640/Fiume%2Bdella%2Brealta%25CC%2580.png\" width=\"640\" /></a></div><br />Il Regno cortese insegna loro come l\'atmosfera di ogni luogo sia sempre contagiosa, nel bene o nel male, e che diffondere la gentilezza nell’interazione con gli altri internauti può bloccare gli atteggiamenti negativi sul web e riportare la pace.<br /><div class=\"separator\" style=\"clear: both; text-align: center;\"><a href=\"https://1.bp.blogspot.com/-eSvz9_lxd8U/Xuhr1JGnVuI/AAAAAAAAhNY/y3UiUkjB0HYiQ_Ai6-b--L9kKhIecRa_QCNcBGAsYHQ/s1600/Regno%2Bcortese.png\" imageanchor=\"1\" style=\"margin-left: 1em; margin-right: 1em;\"><img border=\"0\" data-original-height=\"776\" data-original-width=\"1600\" height=\"310\" src=\"https://1.bp.blogspot.com/-eSvz9_lxd8U/Xuhr1JGnVuI/AAAAAAAAhNY/y3UiUkjB0HYiQ_Ai6-b--L9kKhIecRa_QCNcBGAsYHQ/s640/Regno%2Bcortese.png\" width=\"640\" /></a></div><div class=\"separator\" style=\"clear: both; text-align: center;\"><br /></div>Nella Torre del tesoro imparate a mantenere al sicuro i vostri tesori più preziosi - le informazioni personali.<br /><br /><a href=\"https://1.bp.blogspot.com/-7ttklw9a4tM/Xuhrj-Ikc1I/AAAAAAAAhNI/VQxq7A8UYNo8EZhH8WSZnDmbsCYZXVkYACNcBGAsYHQ/s1600/Torre%2Bdel%2Btesoro.png\" imageanchor=\"1\" style=\"margin-left: 1em; margin-right: 1em; text-align: center;\"><img border=\"0\" data-original-height=\"776\" data-original-width=\"1600\" height=\"310\" src=\"https://1.bp.blogspot.com/-7ttklw9a4tM/Xuhrj-Ikc1I/AAAAAAAAhNI/VQxq7A8UYNo8EZhH8WSZnDmbsCYZXVkYACNcBGAsYHQ/s640/Torre%2Bdel%2Btesoro.png\" width=\"640\" /></a><br /><br />Mentre sul Monte responsabile, la città montuosa di Interland in cui incontrare e chiacchierare con gli altri abitanti, si deve fare molta attenzione a cosa condividere e con chi, perchè le informazioni viaggiano veloci e tra quelli che conoscete c\'è un chiacchierone che le condivide senza controllo.<br /><br /><div class=\"separator\" style=\"clear: both; text-align: center;\"><a href=\"https://1.bp.blogspot.com/-ZxoRqW9cNUg/Xuhrst6N4lI/AAAAAAAAhNM/a1k67f65iSgtsxxTLbTpEUoEYqBu5xd1QCNcBGAsYHQ/s1600/Monte%2Bresponsabile.png\" imageanchor=\"1\" style=\"margin-left: 1em; margin-right: 1em;\"><img border=\"0\" data-original-height=\"776\" data-original-width=\"1600\" height=\"310\" src=\"https://1.bp.blogspot.com/-ZxoRqW9cNUg/Xuhrst6N4lI/AAAAAAAAhNM/a1k67f65iSgtsxxTLbTpEUoEYqBu5xd1QCNcBGAsYHQ/s640/Monte%2Bresponsabile.png\" width=\"640\" /></a></div><br />In occasione del lancio di Interland, insieme a <a href=\"https://mondodigitale.org/it\">Fondazione Mondo Digitale</a>, nuovo partner di “Vivi Internet, al Meglio”, dedicheremo tutto un weekend - Sabato 20 e domenica 21 giugno - alla scoperta degli Interland Lab, laboratori online gratuiti di 40 minuti ciascuno, in cui bambini nella fascia di età tra i 6 e i 13 anni potranno esplorare il mondo di Internet mettendosi alla prova con Interland. Potete iscrivervi <a href=\"https://interland.mondodigitale.org/b/\">a questa pagina</a>.<br /><br />Interland si inserisce all’interno del programma “<a href=\"https://beinternetawesome.withgoogle.com/it_it/\">Vivi Internet, al Meglio</a>”, lanciato da Google nel 2018 per aiutare <a href=\"https://beinternetawesome.withgoogle.com/it_it/periragazzi\">ragazzi</a> e <a href=\"http://g.co/perlefamiglie\">famiglie</a> a vivere il mondo online in modo più consapevole. ll progetto, promosso dal Safer Internet Centre - Generazioni Connesse nell’ambito delle attività di sensibilizzazione ed educazione all’uso consapevole di Internet e delle nuove tecnologie, vede anche la collaborazione di Altroconsumo per quanto riguarda le attività dedicate ai genitori.<br /><br />Oltre a integrare il programma con uno spazio specificamente pensato per i più piccoli, abbiamo ampliato il sito Vivi Internet, al Meglio con una sezione interamente dedicata ai docenti, al <a href=\"http://g.co/peridocenti\">g.co/peridocenti</a>, sviluppata in collaborazione con <a href=\"https://mondodigitale.org/it\">Fondazione Mondo Digitale</a>. Questi contenuti offrono ai docenti gli strumenti e i metodi necessari per insegnare i concetti di base di sicurezza e cittadinanza digitale in classe.  Per scoprire tutte le novità, visitate la pagina di \"Vivi Internet, al Meglio\" all’indirizzo <a href=\"http://g.co/vivinternetalmeglio\">g.co/vivinternetalmeglio</a>.<br /><br /><span class=\"byline-author\">Scritto da: Il Team Google Italy</span><div class=\"feedflare\">\n<a href=\"http://feeds.feedburner.com/~ff/GoogleItaliaBlog?a=UhQkSEAFvA8:zsKV9HeS9YU:yIl2AUoC8zA\"><img src=\"http://feeds.feedburner.com/~ff/GoogleItaliaBlog?d=yIl2AUoC8zA\" border=\"0\"></img></a> <a href=\"http://feeds.feedburner.com/~ff/GoogleItaliaBlog?a=UhQkSEAFvA8:zsKV9HeS9YU:V_sGLiPBpWU\"><img src=\"http://feeds.feedburner.com/~ff/GoogleItaliaBlog?i=UhQkSEAFvA8:zsKV9HeS9YU:V_sGLiPBpWU\" border=\"0\"></img></a>\n</div><img src=\"http://feeds.feedburner.com/~r/GoogleItaliaBlog/~4/UhQkSEAFvA8\" height=\"1\" width=\"1\" alt=\"\"/>', 1592383759, 'tag:blogger.com,1999:blog-12671138.post-3535339060567944902'),
(855, 'en', 12, 'Mirage JS Deep Dive: Using Mirage JS And Cypress For UI Testing (Part 4)', 'https://www.smashingmagazine.com/2020/06/mirage-javascript-cypress-ui-testing/', NULL, 'One of my favorite quotes about software testing is from the Flutter documentation. It says:\n“How can you ensure that your app continues to work as you add more features or change existing functionality? By writing tests.” On that note, this last part of the Mirage JS Deep Dive series will focus on using Mirage to test your JavaScript front-end application.\nNote: This article assumes a Cypress environment. Cypress is a testing framework for UI testing.', 1592389800, 'https://www.smashingmagazine.com/2020/06/mirage-javascript-cypress-ui-testing/'),
(856, 'en', 12, 'Better Reducers With Immer', 'https://www.smashingmagazine.com/2020/06/better-reducers-with-immer/', NULL, 'As a React developer, you should be already familiar with the principle that state should not be mutated directly. You might be wondering what that means (most of us had that confusion when we started out).\nThis tutorial will do justice to that: you will understand what immutable state is and the need for it. You’ll also learn how to use Immer to work with immutable state and the benefits of using it.', 1592310600, 'https://www.smashingmagazine.com/2020/06/better-reducers-with-immer/'),
(857, 'en', 12, 'Smashing Podcast Episode 18 With Mina Markham: How Can I Learn React?', 'https://www.smashingmagazine.com/2020/06/smashing-podcast-episode-18/', NULL, 'In this episode of the Smashing Podcast, we’re talking about learning React. What’s React like to work with, and how can experienced developers get started? I spoke to Mina Markham to find out.\nShow Notes Mina Markham on Twitter Mina’s personal website Weekly Update From Static Sites To End User JAMstack Apps With FaunaDB by Bryan Robinson Is Your Website Stressing Out Visitors? by Suzanna Scacca Mirage JS Deep Dive: Understanding Timing, Response And Passthrough (Part 3) by Kelvin Omereshone Building A Facial Recognition Web Application With React by Adeneye David Abiodun Internationalization In Vue With The Vue I18n Plugin by Timi Omoyeni Transcript Drew McLellan: She is a front-end architect, conference speaker and organizer, and lover of design systems.', 1592283600, 'https://www.smashingmagazine.com/2020/06/smashing-podcast-episode-18/'),
(858, 'en', 13, 'LingoJam', 'https://lingojam.com/', 'Chris Coyier', '<p>I&#8217;ll sometimes search the web for something like &#8220;Small Text Generator&#8221; knowing there will be <a href=\"https://lingojam.com/SmallTextGenerator\">some website</a> that will turn some dumb thing I want to type like:</p>\n<pre rel=\"HTML\" class=\"wp-block-csstricks-code-block language-markup\" data-line=\"\"><code markup=\"tt\">Uhm hi when is that meeting again?</code></pre>\n<p>into something fun like&#8230;</p>\n<pre rel=\"HTML\" class=\"wp-block-csstricks-code-block language-markup\" data-line=\"\"><code markup=\"tt\">ᵁʰᵐ ʰᶦ ʷʰᵉⁿ ᶦˢ ᵗʰᵃᵗ ᵐᵉᵉᵗᶦⁿᵍ ᵃᵍᵃᶦⁿˀ</code></pre>\n<p class=\"explanation\"><strong>Important note about accessibility:</strong> This kind of altered text will read terribly with assistive technology like VoiceOver. Just &#8220;Uhm&#8221; will read as &#8220;modified letter U, modified letter h, modified letter m,&#8221; which doesn&#8217;t convey &#8230; <a href=\"https://css-tricks.com/lingojam/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;LingoJam&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/lingojam/\">LingoJam</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1592405812, 'https://css-tricks.com/?p=313028'),
(859, 'en', 13, 'Web Engine Diversity and Ecosystem Health', 'https://bkardell.com/blog/EcosystemHealth.html', 'Chris Coyier', '<p>As front-end developers, our job is working with browsers. Knowing how many we have and the health of them is always of great interest. As far as numbers go, we have fewer recently than we have in the past. It&#8217;s only <a href=\"https://www.engadget.com/microsoft-edge-windows-update-163054502.html\">this month</a> that Edge is starting to auto-update browsers to the Chromium version, yet another notable milestone in the shrinking number of browsers.</p>\n<p>A few years back, Rachel Nabors <a href=\"https://css-tricks.com/the-ecological-impact-of-browser-diversity/\">likened</a> the situation to a biological ecosystem and how diversity &#8230; <a href=\"https://css-tricks.com/web-engine-diversity-and-ecosystem-health/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;Web Engine Diversity and Ecosystem Health&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/web-engine-diversity-and-ecosystem-health/\">Web Engine Diversity and Ecosystem Health</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1592322396, 'https://css-tricks.com/?p=313013'),
(860, 'en', 13, 'Everything You Need to Know About FLIP Animations in React', 'https://css-tricks.com/everything-you-need-to-know-about-flip-animations-in-react/', 'Kirill Vasiltsov', '<p>With a very recent Safari update, <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/Web_Animations_API\">Web Animations API</a> (WAAPI) is <a href=\"https://caniuse.com/#feat=web-animation\">now supported without a flag</a> in all modern browsers (except IE). &#160;Here’s <a href=\"https://codepen.io/danwilson/pen/xGBKVq\">a handy Pen</a> where you can check which features your browser supports. The WAAPI is a nice way to do animation (that needs to be done in JavaScript) because it’s native — meaning it requires no additional libraries to work. If you’re completely new to WAAPI, here’s <a href=\"https://danielcwilson.com/blog/2015/07/animations-part-1/\">a very good introduction by Dan Wilson</a>.</p>\n<p>One of &#8230; <a href=\"https://css-tricks.com/everything-you-need-to-know-about-flip-animations-in-react/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;Everything You Need to Know About FLIP Animations in React&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/everything-you-need-to-know-about-flip-animations-in-react/\">Everything You Need to Know About FLIP Animations in React</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1592318404, 'https://css-tricks.com/?p=312119'),
(861, 'en', 13, 'What is Developer Experience (DX)?', 'https://css-tricks.com/what-is-developer-experience-dx/', 'Chris Coyier', '<p>Developer Experience<a href=\"#fn:1\">¹</a> is a term<a href=\"#fn:1\">²</a> with a self-declaring meaning — <em class=\"yellow-em\">the experience of developers</em> — but it eludes definition in the sense that people invoke it at different times for different reasons referring to different things. For instance, our own Sarah Drasner&#8217;s current job title is &#8220;VP of Developer Experience&#8221; at Netlify, so it&#8217;s a very real thing. But a job title is just <em>one</em> way the term is used. Let&#8217;s dig in a bit and apply it &#8230; <a href=\"https://css-tricks.com/what-is-developer-experience-dx/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;What is Developer Experience (DX)?&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/what-is-developer-experience-dx/\">What is Developer Experience (DX)?</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1592263896, 'https://css-tricks.com/?p=311245'),
(872, 'en', 5, 'Refactoring optional chaining into a large codebase: lessons learned', 'http://feedproxy.google.com/~r/leaverou/~3/dTr3Z1-7U7I/', 'Lea Verou', 'Now that optional chaining is supported across the board, I decided to finally refactor Mavo to use it (yes, yes, we do provide a transpiled version as well for older browsers, settle down). This is a moment I have been waiting for a long time, as I think optional chaining is the single most substantial [&#8230;]', 1592492168, 'https://lea.verou.me/?p=3054'),
(898, 'en', 12, 'What Vitruvius Can Teach Us About Web Design', 'https://www.smashingmagazine.com/2020/06/vitruvius-web-design/', NULL, 'There’s no escaping the ancient masters. Their shadows loom large over philosophy, literature, architecture, warfare, and… web design? Believe it or not, yes. Although Plato infamously omitted CSS Grid from from the final draft of The Republic, there is nonetheless plenty the old heads can teach us about web development.\nToday’s lecture is about architecture, and how some of its core tenets apply to the worldwide web. Architectural terms are not unusual in web development, and for good reason.', 1592560800, 'https://www.smashingmagazine.com/2020/06/vitruvius-web-design/'),
(899, 'en', 12, 'Solving Common Cross-Platform Issues When Working With Flutter', 'https://www.smashingmagazine.com/2020/06/common-cross-platform-issues-flutter/', NULL, 'I’ve seen a lot of confusion online regarding Web development with Flutter and, often, it’s sadly for the wrong reasons.\nSpecifically, people sometimes confuse it with the older Web-based mobile (and desktop) cross-platform frameworks, which basically were just Web pages running within browsers running within a wrapper app.\nThat was truly cross-platform in the sense that the interfaces were the same anyway because you only had access to the interfaces normally accessible on the Web.', 1592476200, 'https://www.smashingmagazine.com/2020/06/common-cross-platform-issues-flutter/'),
(900, 'en', 13, 'Easing Animations in Canvas', 'https://css-tricks.com/easing-animations-in-canvas/', 'Darshan Somashekar', '<p>The <code>&#60;canvas&#62;</code> element in HTML and Canvas API in JavaScript combine to form one of the main raster graphics and animation possibilities on the web. A common canvas use-case is programmatically generating images for websites, particularly <em>games</em>. That’s exactly what I’ve done in <a href=\"https://solitaired.com/\">a website I built for playing Solitaire</a>. The cards, including all their movement, is all done in canvas.</p>\n<p>In this article, let’s look specifically at animation in canvas and techniques to make them look smoother. &#8230; <a href=\"https://css-tricks.com/easing-animations-in-canvas/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;Easing Animations in Canvas&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/easing-animations-in-canvas/\">Easing Animations in Canvas</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1592577025, 'https://css-tricks.com/?p=312713'),
(901, 'en', 13, 'Just another +1 for subgrid', 'https://css-tricks.com/just-another-1-for-subgrid/', 'Chris Coyier', '<p>I&#8217;d say 85% of my grid usage is in one of these two categories&#8230;</p>\n<ol>\n<li>I just need some pretty basic (probably equal width) columns that ends up being something like like <code>grid-template-columns: repeat(3, minmax(0, 1fr));</code> <a href=\"https://css-tricks.com/preventing-a-grid-blowout/\">to be safe</a>.</li>\n<li>Actually doing some real layout where five minutes in I realize I&#8217;d really like <code>subgrid</code>.</li>\n</ol>\n<p>Subgrid? It&#8217;s a nice intuitive way to have a child element on the grid inherit relevant grid lines from the parent grid.</p>\n<p>Here&#8217;s<a href=\"https://vimeo.com/422929734\"> a great </a>&#8230; <a href=\"https://css-tricks.com/just-another-1-for-subgrid/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;Just another +1 for subgrid&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/just-another-1-for-subgrid/\">Just another +1 for subgrid</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1592577001, 'https://css-tricks.com/?p=313071'),
(902, 'en', 13, 'Where Do You Learn HTML & CSS in 2020?', 'https://css-tricks.com/where-do-you-learn-html-css-in-2019/', 'Chris Coyier', '<p>The question of how and where to learn HTML &#38; CSS is a highly reasonable thing to ask. The answer depends on all sorts of things: how serious you are, your current foundation, what other resources are available to you, what you hope to do with what you learn, and how much time you have, among probably a zillion other things.</p>\n<p>Let&#8217;s look at a bunch of options and you can choose the ones that feel right to you. </p>\n<p>You&#8230; <a href=\"https://css-tricks.com/where-do-you-learn-html-css-in-2019/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;Where Do You Learn HTML &#038; CSS in 2020?&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/where-do-you-learn-html-css-in-2019/\">Where Do You Learn HTML &#038; CSS in 2020?</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1592572200, 'http://css-tricks.com/?p=281191'),
(903, 'en', 13, 'Stay DRY Using axios for API Requests', 'https://css-tricks.com/stay-dry-using-axios-for-api-requests/', 'David Atanda', '<p>HTTP requests are a crucial part of any web application that’s communicating with a back-end server. The front end needs some data, so it asks for it via a network HTTP request (or Ajax, as it tends to be called), and the server returns an answer. Almost every website these days does this in some fashion.</p>\n<p>With a larger site, we can expect to see more of this. More data, more APIs, and more special circumstances. As sites grow like &#8230; <a href=\"https://css-tricks.com/stay-dry-using-axios-for-api-requests/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;Stay DRY Using axios for API Requests&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/stay-dry-using-axios-for-api-requests/\">Stay DRY Using axios for API Requests</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1592492545, 'https://css-tricks.com/?p=312657'),
(904, 'en', 13, 'Building a hexagonal grid using CSS grid', 'https://ninjarockstar.dev/css-hex-grids/', 'Chris Coyier', '<p>I think of grids as arrangements of rectangles with vertical and horizontal lines running through. And they are, but that doesn&#8217;t mean we can&#8217;t still do clever things in how we place things on those grids and what we do with the elements afterwards. </p>\n<p>In this demo by Jesse Breneman, a grid of hexagons is created by setting up the grid columns with math such that each block can span over three columns and two rows so that the blocks &#8230; <a href=\"https://css-tricks.com/building-a-hexagonal-grid-using-css-grid/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;Building a hexagonal grid using CSS grid&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/building-a-hexagonal-grid-using-css-grid/\">Building a hexagonal grid using CSS grid</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1592491341, 'https://css-tricks.com/?p=313064'),
(905, 'en', 13, 'Advice for Complex CSS Illustrations', 'https://css-tricks.com/advice-for-complex-css-illustrations/', 'Jhey Tompkins', '<p>If you were to ask me what question I hear most about front-end development, I’d say it’s<em>&#8220;How do I get better at CSS?&#8221;.</em> That question usually comes up after sharing a CSS illustration I have made. It&#8217;s something <a href=\"https://codepen.io/jh3y/pens/\">I love to do over on CodePen</a>.</p>\n<p>To many, CSS is this mythical beast that can’t be tamed. <a href=\"https://twitter.com/chriscoyier/status/1248088743002677248\">This tweet</a> from Chris made me chuckle because, although ironic, there’s a lot of truth to it. That said, what if I &#8230; <a href=\"https://css-tricks.com/advice-for-complex-css-illustrations/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;Advice for Complex CSS Illustrations&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/advice-for-complex-css-illustrations/\">Advice for Complex CSS Illustrations</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1592421282, 'https://css-tricks.com/?p=312636'),
(922, 'en', 12, 'A Monthly Update On All Things Smashing', 'https://www.smashingmagazine.com/2020/06/monthly-roundup-06-2020/', NULL, 'The entire Smashing team has been doing its very best to bring you live sessions with real experts &mdash; people with practical experience who love to share what they have learned throughout their careers. We organized Smashing Meets on three days &mdash; events that were open to everyone in the web community. With sessions on performance, CSS, GraphQL, and creative courage, we made sure to leave plenty of time for Q&amp;A, networking, competitions and prizes.', 1592589600, 'https://www.smashingmagazine.com/2020/06/monthly-roundup-06-2020/'),
(923, 'en', 13, 'Patternico', 'https://patternico.com/', 'Chris Coyier', '<p>I remember searching for tutorials for making seamless patterns in Photoshop<a href=\"#fn:1\">¹</a> all the time back in the day. </p>\n<p>It&#8217;s fun to see this little website for building repeating patterns as its one job. It does everything you&#8217;d expect: pick a background, drag some decorations onto it and position them (overlapping an edge is fine, which is the hard part, and makes the designs look less griddy), color them, and away you go. </p>\n<ol>\n<li>The <a href=\"https://www.youtube.com/watch?v=uB0IG2x2wPc\">trick</a> is to make a square </li>\n</ol>\n<p>&#8230; <a href=\"https://css-tricks.com/patternico/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;Patternico&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/patternico/\">Patternico</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1592661017, 'https://css-tricks.com/?p=313231'),
(934, 'en', 12, 'An Introduction To SWR: React Hooks For Remote Data Fetching', 'https://www.smashingmagazine.com/2020/06/introduction-swr-react-hooks-remote-data-fetching/', NULL, 'SWR is a lightweight library created by Vercel (formerly ZEIT) that allows fetching, caching, or refetching data in realtime using React Hooks. It’s built with React Suspense which lets your components &ldquo;wait&rdquo; for something before they can render, including data. SWR ships also with great features such as dependent fetching, focus on revalidation, scroll position recovery, and so on. It’s also a very powerful tool since it’s backend agnostic and has good support for TypeScript.', 1592827200, 'https://www.smashingmagazine.com/2020/06/introduction-swr-react-hooks-remote-data-fetching/'),
(960, 'en', 10, 'CSS background-repeat: round', 'http://feedproxy.google.com/~r/Bludice/~3/5Yd0wUobDv4/css-background-repeat-round', 'David Walsh', '<p>The CSS spec is full of gems that sneak their way past most of us web designers and developers. Stuff like :focus-within, prefers-reduced-motion, and prefers-color-scheme suddenly make their way into CSS without us really finding out for months or years. One such example is background-repeat: round. background-repeat: round repeats a background image without clipping! .my-element [&#8230;]</p>\n<p>The post <a rel=\"nofollow\" href=\"https://davidwalsh.name/css-background-repeat-round\">CSS background-repeat: round</a> appeared first on <a rel=\"nofollow\" href=\"https://davidwalsh.name\">David Walsh Blog</a>.</p>\n<p><a href=\"https://tkjs.us/dwb\"><img style=\"margin:0 auto\" alt=\"\" src=\"https://davidwalsh.name/demo/tjs_block-1.svg\"></a></p>\n', 1592924220, 'https://davidwalsh.name/?p=27151'),
(961, 'en', 12, 'How Web Designers Can Help Restaurants Move Into Digital Experiences', 'https://www.smashingmagazine.com/2020/06/web-designers-help-restaurants-digital-experiences/', NULL, 'As much as I’ve always loved the experience of going out to eat and ordering in takeout, it’s very rare that I enjoy visiting a restaurant’s website. But I get it. The restaurant industry tends to run on very slim profit margins, so it’s hard to justify spending money on a professionally designed website when all they want it to do is list their hours of operation and menu.', 1592913600, 'https://www.smashingmagazine.com/2020/06/web-designers-help-restaurants-digital-experiences/'),
(962, 'en', 13, 'WebP Image Support Coming to iOS 14', 'https://developer.apple.com/documentation/safari-release-notes/safari-14-beta-release-notes', 'Geoff Graham', '<p>Apple announced a ton of new updates at yesterday&#8217;s <a href=\"https://www.apple.com/apple-events/june-2020/\">WWDC20</a> keynote address, from new hardware to updated applications. There&#8217;s lots to gawk at and enough device-envy to go around.</p>\n<p>But there&#8217;s one little line in the <a href=\"https://developer.apple.com/documentation/safari-release-notes/safari-14-beta-release-notes\">Safari 14 Beta release notes</a> that caught my eye:</p>\n<blockquote class=\"wp-block-quote\">\n<p>Added WebP image support.</p>\n</blockquote>\n<p>&#x1f389;&#x1f389;&#x1f389;</p>\n<p>This excites me because WebP is a super progressive format that encodes images in lossless and lossy formats that we get with other image formats we already use, like JPEG, &#8230; <a href=\"https://css-tricks.com/webp-image-support-coming-to-ios-14/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;WebP Image Support Coming to iOS 14&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/webp-image-support-coming-to-ios-14/\">WebP Image Support Coming to iOS 14</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1592954590, 'https://css-tricks.com/?p=313886'),
(963, 'en', 13, 'Let’s Make a Multi-Thumb Slider That Calculates The Width Between Thumbs', 'https://css-tricks.com/lets-make-a-multi-thumb-slider-that-calculates-the-width-between-thumbs/', 'Simdi Jinkins', '<p>HTML has an <code>&#60;input type=\"range\"&#62;</code>, which is, you could argue, the simplest type of proportion slider. Wherever the thumb of that slider ends up could represent a proportion of whatever is before and whatever is after it (using the <code>value</code> and <code>max</code> attributes). Getting fancier, it’s possible to build <a href=\"https://css-tricks.com/multi-thumb-sliders-general-case/\">a multi-thumb slider</a>. But we’ve got another thing in mind today… a proportion slider with multiple thumbs, and sections that cannot overlap.</p>\n<p>Here’s what we’ll be building today:</p>\n<p>CodePen&#8230; <a href=\"https://css-tricks.com/lets-make-a-multi-thumb-slider-that-calculates-the-width-between-thumbs/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;Let&#8217;s Make a Multi-Thumb Slider That Calculates The Width Between Thumbs&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/lets-make-a-multi-thumb-slider-that-calculates-the-width-between-thumbs/\">Let&#8217;s Make a Multi-Thumb Slider That Calculates The Width Between Thumbs</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1592924096, 'https://css-tricks.com/?p=312728'),
(964, 'en', 13, 'An Overview of Scroll Technologies', 'https://css-tricks.com/an-overview-of-scroll-technologies/', 'Zach Saucier', '<p>Scroll-related animations have been used on the web for years. In recent years, they’ve started to become more common, perhaps in part due to devices being higher-performing and thus able to handle more animation.&#160;</p>\n<p>There are a number of scroll related technologies out there, so this article’s aim is to provide an overview of them and tools to help choose the one that’s right for you. I’d argue that these technologies can be broken down into two broad categories: ones &#8230; <a href=\"https://css-tricks.com/an-overview-of-scroll-technologies/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;An Overview of Scroll Technologies&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/an-overview-of-scroll-technologies/\">An Overview of Scroll Technologies</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1592862742, 'https://css-tricks.com/?p=312080');
INSERT INTO `aggregator_item` (`iid`, `langcode`, `fid`, `title`, `link`, `author`, `description`, `timestamp`, `guid`) VALUES
(965, 'en', 13, 'Rough Notation', 'https://roughnotation.com/', 'Chris Coyier', '<p><a href=\"https://roughnotation.com/\">This is a neat little library. </a>It uses SVG to insert hand-drawn looking annotations to elements (probably text), like underlines and box highlights (there are 6 design options, all configurable). Super clever.</p>\n<p>Here&#8217;s a little demo:</p>\n<p>CodePen Embed Fallback</p>\n<p>Aside from it just being cool, I really like how it was released. You can use it from npm. It&#8217;s ready to be used via ES6 imports. You can just use it as a <code>&#60;script src&#62;</code>. Then, if you <em>happen</em>&#8230; <a href=\"https://css-tricks.com/rough-notation/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;Rough Notation&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/rough-notation/\">Rough Notation</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1592862707, 'https://css-tricks.com/?p=313163'),
(966, 'en', 13, 'Using Custom Property “Stacks” to Tame the Cascade', 'https://css-tricks.com/using-custom-property-stacks-to-tame-the-cascade/', 'Miriam Suzanne', '<p>Since the inception of CSS in 1994, the cascade and inheritance have defined how we design on the web. Both are powerful features but, as authors, we&#8217;ve had very little control over how they interact. Selector specificity and source order provide some minimal &#8220;layering&#8221; control, without a lot of nuance &#8212; and inheritance requires an <em>unbroken lineage</em>. <strong>Now, CSS Custom Properties allow us to manage and control both cascade and inheritance in new ways.</strong></p>\n<p>I want to show you &#8230; <a href=\"https://css-tricks.com/using-custom-property-stacks-to-tame-the-cascade/\" class=\"read-more\">Read article <span class=\"screen-reader-text\"> &#8220;Using Custom Property &#8220;Stacks&#8221; to Tame the Cascade&#8221;</span></a></p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/using-custom-property-stacks-to-tame-the-cascade/\">Using Custom Property &#8220;Stacks&#8221; to Tame the Cascade</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 1592837269, 'https://css-tricks.com/?p=312969');
