r\n	background-color: #9F9;\r\n}\r\naside {\r\n	background-color: #FC9;\r\n}\r\nfooter div {\r\n	background-color: #9CC;\r\n}\r\na {\r\n	text-decoration: none;\r\n	color: inherit;\r\n}\r\n/*ora restringo la finestra del browser a 768 pixel e faccio gli aggiustamenti necessari*/\r\n@media screen and (max-width : 768px) {\r\nbody {\r\n	width: 768px;\r\n}\r\nnav {\r\n	float: none;\r\n	width: 768px;\r\n}\r\nnav > ul > li > ul {\r\n	display: none;\r\n}\r\nnav > ul > li:hover > ul {\r\n	display: block;\r\n}\r\nnav > ul > li {\r\n	position: relative;\r\n}\r\nnav > ul > li:nth-child(1) > ul {\r\n	position: absolute;\r\n	left: 130px;\r\n	top: 0;\r\n	color: #F66;\r\n}\r\nnav > ul > li:nth-child(2) > ul {\r\n	position: absolute;\r\n	left: 130px;\r\n	top: -80%;\r\n	color: #FC3;\r\n}\r\nnav > ul > li:nth-child(3) > ul {\r\n	position: absolute;\r\n	left: 130px;\r\n	bottom: 0;\r\n	color: #C3C;\r\n}\r\nfooter > div {\r\n	width: 230px;\r\n}\r\nfooter > div:nth-child(2) {\r\n	margin-right: 13px;\r\n	margin-left: 13px;\r\n}\r\n}\r\n/*ora restringo la finestra del browser a 480 pixel e faccio gli aggiustamenti necessari*/\r\n @media screen and (max-width : 480px) {\r\nbody {\r\n	width: 480px;\r\n}\r\nnav {\r\n	width: 480px;\r\n}\r\nsection {\r\n	width: 480px;\r\n	float: none;\r\n}\r\naside {\r\n	float: none;\r\n	width: 480px;\r\n	margin-left: 0;\r\n	margin-bottom: 20px;\r\n}\r\nfooter > div {\r\n	width: 140px;\r\n}\r\nfooter > div:nth-child(2) {\r\n	margin-right: 10px;\r\n	margin-left: 10px;\r\n}\r\n/*ora restringo la finestra del browser a 320 pixel e faccio gli aggiustamenti necessari*/\r\n @media screen and (max-width : 320px) {\r\n body {\r\n	 width: 320px;\r\n}\r\nnav {\r\n 	width:320px;\r\n}\r\nnav > ul > li:nth-child(1) > ul {\r\n 	left: 100px;\r\n}\r\nnav > ul > li:nth-child(2) > ul {\r\n	left: 100px;\r\n}\r\nnav > ul > li:nth-child(3) > ul {\r\n 	left: 100px;\r\n}\r\nsection {\r\n 	width: 320px;\r\n}\r\narticle {\r\n	padding-bottom: 80px;\r\n}\r\naside {\r\n	width:320px;\r\n}\